import React, { useState } from 'react'
import './App.css'
import Task from './Task'

function TaskList() {

    // const[task,setTask]=useState({
    //     id:'',
    //     libelle:'',
    //     delete:false,
    //     termine:false,
    // })
    const [taskList, setTaskList] = useState([
        {
            id:0,
            libelle:'Moi',
            complete:false,
            delete:false
        }
    ])

    const hamdleSubmit = (t) => {
        t.preventDefault()
        // console.log(new FormData(t.target))
        const newTask = new FormData(t.target)
        const libelle = newTask.get('task')
        let taskListCopy = [...taskList]
        const task = {
            id: taskListCopy.length,
            libelle: libelle,
            complete: false,
            delete: false
        }
        taskListCopy.push(task)
        console.log(taskListCopy)
        // setTaskList(taskListCopy)
    }

    return (
        <div className='task-list-container'>
            <section>
                <form className='task-form' onSubmit={(e) => hamdleSubmit(e)}>
                    <label className='task-label'>Add Task</label>
                    <input
                        name='task'
                        className='task-input'
                        placeholder='Enter your task'
                    />
                    <button className='task-submit-btn' type='submit'>Add</button>
                </form>
            </section>
            <section className='task-list '>
                {
                    taskList.map((task) => (
                         console.log(task)
                        
                    ))
                }
            </section>


        </div>
    )
}

export default TaskList
